import os, csv, json, sys
from pyscipopt import Model, quicksum

DATA = "/app/data"
OUT = "/app/submissions/solution.csv"
LOG = "/app/submissions/solve_log.md"

def read_csv(name):
    with open(os.path.join(DATA, name), newline="") as f:
        return list(csv.DictReader(f))

days = read_csv("days.csv")
shifts = read_csv("shifts.csv")
skills = read_csv("skills.csv")
contracts = read_csv("contracts.csv")
rest_rules = read_csv("contract_rest_rules.csv")
dayoff_rules = read_csv("contract_dayoff_rules.csv")
period_rules = read_csv("period_consecutiveness_rules.csv")
nurses = read_csv("nurses.csv")
nurse_skills = read_csv("nurse_skills.csv")
coverage = read_csv("coverage_requirements.csv")
forb_succ = read_csv("shift_forbidden_successions.csv")
preassign = read_csv("preassignments.csv")
prefs = read_csv("preferences.csv")
incomp = read_csv("incompatibilities.csv")
workteam = read_csv("workteam_rules.csv")
charge_rules = read_csv("charge_coverage_rules.csv")
fairness = read_csv("fairness_rules.csv")
with open(os.path.join(DATA, "config.json")) as f:
    config = json.load(f)

W = config["objective_weights"]

day_idx = {r["day"]: int(r["day_index"]) for r in days}
day_weekday = {r["day"]: r["weekday"] for r in days}
day_is_weekend = {r["day"]: int(r["is_weekend"]) for r in days}
day_is_sunday = {r["day"]: int(r["is_sunday"]) for r in days}
day_is_holiday = {r["day"]: int(r["is_holiday"]) for r in days}
day_weekend_id = {r["day"]: r["weekend_id"] for r in days}
day_list = sorted(days, key=lambda r: int(r["day_index"]))
DAYS = [r["day"] for r in day_list]
N = len(DAYS)

shift_period = {r["shift_id"]: r["period"] for r in shifts}
shift_start = {r["shift_id"]: int(r["start_minute"]) for r in shifts}
shift_dur = {r["shift_id"]: int(r["duration_minutes"]) for r in shifts}
shift_night = {r["shift_id"]: int(r["is_night"]) for r in shifts}

contract = {r["contract_id"]: r for r in contracts}
nurse_contract = {r["nurse_id"]: r["contract_id"] for r in nurses}
NURSES = [r["nurse_id"] for r in nurses]

# eligibility: (nurse, skill, shift) -> standard flag
elig = {}
for r in nurse_skills:
    elig[(r["nurse_id"], r["skill_id"], r["shift_id"])] = int(r["standard"])

# preassignments: all hard A in this instance
hard_A = {}
soft_pre = []
for r in preassign:
    n, d = r["nurse_id"], r["day"]
    if r["assignment_type"] == "fixed_status" and r["shift_id"] == "A":
        if int(r["hard"]) == 1:
            hard_A[(n, d)] = True
        else:
            soft_pre.append((n, d, int(r["penalty"])))
    elif r["assignment_type"] == "fixed_shift":
        if int(r["hard"]) == 1:
            hard_A[(n, d)] = True  # block other states; shift handled separately
            # store fixed shift
            hard_A[(n, d)] = (r["shift_id"], r["skill_id"])
        else:
            soft_pre.append((n, d, int(r["penalty"])))
    elif r["assignment_type"] in ("fixed_rest", "fixed_off"):
        if int(r["hard"]) == 1:
            hard_A[(n, d)] = None  # rest

# Separate: hard_fixed_shift[(n,d)] = (shift, skill)
hard_fixed_shift = {}
hard_rest = set()
hard_A_only = set()
for r in preassign:
    n, d = r["nurse_id"], r["day"]
    if int(r["hard"]) != 1:
        continue
    if r["assignment_type"] == "fixed_status" and r["shift_id"] == "A":
        hard_A_only.add((n, d))
    elif r["assignment_type"] == "fixed_shift":
        hard_fixed_shift[(n, d)] = (r["shift_id"], r["skill_id"])
    elif r["assignment_type"] in ("fixed_rest", "fixed_off"):
        hard_rest.add((n, d))

# coverage
cov = {}
for r in coverage:
    key = (r["day"], r["period"], r["skill_id"])
    cov[key] = (int(r["min_required"]), int(r["optimal_required"]), int(r["max_allowed"]))

# incompatibilities
inc_hard_shift = []  # (a, b, shift or None)
inc_soft = []  # (a, b, scope, shift, penalty)
for r in incomp:
    a, b = r["nurse_id_a"], r["nurse_id_b"]
    sh = r["shift_id"] if r["shift_id"] else None
    if int(r["hard"]) == 1:
        inc_hard_shift.append((a, b, sh))
    else:
        inc_soft.append((a, b, r["scope"], sh, int(r["penalty"])))

# charge rules
charge = []
for r in charge_rules:
    pool = [x for x in r["nurse_ids"].split(";") if x]
    charge.append({
        "scope": r["day_scope"],
        "period": r["period"],
        "skill": r["skill_id"],
        "pool": pool,
        "min": int(r["min_members"]),
        "hard": int(r["hard"]),
        "penalty": int(r["penalty"]),
    })

# fairness rules
fair = []
for r in fairness:
    pool = [x for x in r["nurse_ids"].split(";") if x]
    fair.append({
        "metric": r["metric"],
        "scope": r["day_scope"],
        "period": r["period"],
        "skill": r["skill_id"],
        "allowed": int(r["allowed_difference"]),
        "hard": int(r["hard"]),
        "penalty": int(r["penalty"]),
        "pool": pool,
    })

# period run max
period_max = {}
for r in period_rules:
    period_max[r["period"]] = int(r["max_consecutive_assignments"])

# Build model
model = Model("nurse_rostering")
model.setParam("gaprel", 0.0005)
time_limit = 300.0
env = os.environ.get("ORCLAW_SOLVE_TIME_LIMIT_SECONDS")
if env is not None:
    try:
        time_limit = min(time_limit, float(env))
    except ValueError:
        pass
model.setParam("limits/time", time_limit)

x = {}  # (n, d, s, k)
a = {}  # (n, d) status A
nonstd_count = 0

# Determine allowed days for each nurse (not hard rest, not hard A, not hard fixed shift)
for n in NURSES:
    for d in DAYS:
        if (n, d) in hard_rest:
            continue
        if (n, d) in hard_A_only:
            a[(n, d)] = model.addVar(name=f"a_{n}_{d}", vtype="B", lb=1, ub=1, obj=0.0)
            continue
        if (n, d) in hard_fixed_shift:
            continue
        # status A optional
        a[(n, d)] = model.addVar(name=f"a_{n}_{d}", vtype="B", lb=0, ub=1, obj=0.0)
        for (nn, kk, ss), std in elig.items():
            if nn != n:
                continue
            if (n, d, ss, kk) in x:
                continue
            x[(n, d, ss, kk)] = model.addVar(name=f"x_{n}_{d}_{ss}_{kk}", vtype="B", lb=0, ub=1, obj=0.0)
            if std == 0:
                nonstd_count += 1

# Hard fixed shifts: create var fixed to 1
for (n, d), (ss, kk) in hard_fixed_shift.items():
    if (n, kk, ss) in elig:
        x[(n, d, ss, kk)] = model.addVar(name=f"x_{n}_{d}_{ss}_{kk}", vtype="B", lb=1, ub=1, obj=0.0)
        if elig[(n, kk, ss)] == 0:
            nonstd_count += 1

# One state per nurse-day
for n in NURSES:
    for d in DAYS:
        if (n, d) in hard_rest:
            continue
        terms = []
        for key, v in x.items():
            if key[0] == n and key[1] == d:
                terms.append(v)
        if (n, d) in a:
            terms.append(a[(n, d)])
        if terms:
            model.addCons(quicksum(terms) <= 1, name=f"one_{n}_{d}")

# Coverage
cov_vars = {}
for (d, p, k), (mn, opt, mx) in cov.items():
    terms = [v for key, v in x.items() if key[1] == d and key[3] == k and shift_period.get(key[2]) == p]
    C = quicksum(terms) if terms else 0
    cov_vars[(d, p, k)] = C
    if mn > 0 or opt > 0:
        sm = model.addVar(name=f"sm_{d}_{p}_{k}", vtype="C", lb=0, ub=opt if opt else 99, obj=0.0)
        so = model.addVar(name=f"so_{d}_{p}_{k}", vtype="C", lb=0, ub=opt if opt else 99, obj=0.0)
        ov = model.addVar(name=f"ov_{d}_{p}_{k}", vtype="C", lb=0, ub=99, obj=0.0)
        model.addCons(C + sm >= mn, name=f"covmin_{d}_{p}_{k}")
        model.addCons(C + so >= opt, name=f"covopt_{d}_{p}_{k}")
        model.addCons(C - ov <= mx, name=f"covmax_{d}_{p}_{k}")
        # objective
        model.chgVarObj(sm, W["insufficient_staffing"])
        model.chgVarObj(so, W["understaffing"])
        model.chgVarObj(ov, W["exceeding_staffing"])

# Contract rules
def contract_of(n):
    return contract[nurse_contract[n]]

for n in NURSES:
    c = contract_of(n)
    workdays = set(c["working_weekdays"].split(";"))
    min_a, max_a = int(c["min_assignments"]), int(c["max_assignments"])
    min_w, max_w = int(c["min_work_minutes"]), int(c["max_work_minutes"])
    avg_w = int(c["average_work_minutes"])
    max_consec_work = int(c["max_consecutive_working_days"])
    max_consec_off = int(c["max_consecutive_days_off"])
    min_rest = int(c["min_rest_minutes"])
    max_sun = int(c["max_sundays"])
    max_we = int(c["max_weekends"])
    max_hol = int(c["max_holidays"])

    # counted assignment indicator per day
    wvar = {}
    for d in DAYS:
        terms = []
        for key, v in x.items():
            if key[0] == n and key[1] == d:
                terms.append(v)
        if (n, d) in a and day_weekday[d] in workdays:
            terms.append(a[(n, d)])
        if terms:
            wvar[d] = quicksum(terms)
        else:
            wvar[d] = 0

    total_assign = quicksum([wvar[d] for d in DAYS])
    model.addCons(total_assign >= min_a, name=f"minassign_{n}")
    model.addCons(total_assign <= max_a, name=f"maxassign_{n}")

    # work minutes
    wmin_terms = []
    for key, v in x.items():
        if key[0] == n:
            wmin_terms.append(shift_dur[key[2]] * v)
    for d in DAYS:
        if (n, d) in a and day_weekday[d] in workdays:
            wmin_terms.append(avg_w * a[(n, d)])
    total_work = quicksum(wmin_terms) if wmin_terms else 0
    model.addCons(total_work >= min_w, name=f"minwork_{n}")
    model.addCons(total_work <= max_w, name=f"maxwork_{n}")

    # max consecutive working days
    for i in range(N - max_consec_work + 1):
        window = DAYS[i:i+max_consec_work+1]
        model.addCons(quicksum([wvar[d] for d in window]) <= max_consec_work, name=f"maxworkstreak_{n}_{i}")

    # max consecutive days off
    for i in range(N - max_consec_off + 1):
        window = DAYS[i:i+max_consec_off+1]
        model.addCons(quicksum([1 - wvar[d] for d in window]) <= max_consec_off, name=f"maxoffstreak_{n}_{i}")

    # Sundays, weekends, holidays
    sun_terms = [wvar[d] for d in DAYS if day_is_sunday[d]]
    if sun_terms:
        model.addCons(quicksum(sun_terms) <= max_sun, name=f"maxsun_{n}")
    we_terms = [wvar[d] for d in DAYS if day_is_weekend[d]]
    if we_terms:
        model.addCons(quicksum(we_terms) <= max_we, name=f"maxwe_{n}")
    hol_terms = [wvar[d] for d in DAYS if day_is_holiday[d]]
    if hol_terms:
        model.addCons(quicksum(hol_terms) <= max_hol, name=f"maxhol_{n}")

    # Rest between consecutive detailed shifts (baseline 660)
    for i in range(N - 1):
        d1, d2 = DAYS[i], DAYS[i+1]
        # If both days have detailed shifts, rest must be >= 660
        # rest = start(d2) - (start(d1)+dur(d1)) >= 660
        # Violations: pairs where start(d2) - start(d1) - dur(d1) < 660
        for (n1, d1_, s1, k1), v1 in x.items():
            if n1 != n or d1_ != d1:
                continue
            for (n2, d2_, s2, k2), v2 in x.items():
                if n2 != n or d2_ != d2:
                    continue
            rest = shift_start[s2] - shift_start[s1] - shift_dur[s1]
            if rest < min_rest:
                model.addCons(v1 + v2 <= 1, name=f"rest_{n}_{d1}_{s1}_{d2}_{s2}")

    # 6-consecutive rest rule (2100 min)
    # If 6 consecutive counted assignments end at day i, next shift needs 2100 rest
    # Simplified: if days i-5..i all counted, and day i+1 has shift s2, need rest >= 2100
    for i in range(5, N - 1):
        window = DAYS[i-5:i+1]
        d_next = DAYS[i+1]
        # indicator that all 6 days are counted
        # Use: sum of (1 - wvar) over window == 0
        # For each shift on d_next, if rest < 2100, forbid
        for (n2, d2_, s2, k2), v2 in x.items():
            if n2 != n or d2_ != d_next:
                continue
            # check rest from each possible shift on day i
            bad = False
            for (n1, d1_, s1, k1), v1 in x.items():
                if n1 != n or d1_ != DAYS[i]:
                    continue
                rest = shift_start[s2] - shift_start[s1] - shift_dur[s1]
                if rest < 2100:
                    bad = True
            if bad:
                # If all 6 days counted AND v2=1, infeasible
                # Approximate: sum wvar over window >= 6 - v2
                model.addCons(quicksum([wvar[d] for d in window]) + v2 <= 6, name=f"rest6_{n}_{i}_{s2}")

    # Day-off after 6 consecutive counted
    for i in range(5, N - 1):
        window = DAYS[i-5:i+1]
        d_next = DAYS[i+1]
        model.addCons(quicksum([wvar[d] for d in window]) + wvar[d_next] <= 6, name=f"dayoff6_{n}_{i}")

# Period consecutiveness
for n in NURSES:
    for p, mx in period_max.items():
        for i in range(N - mx + 1):
            window = DAYS[i:i+mx+1]
            terms = []
            for d in window:
                for key, v in x.items():
                    if key[0] == n and key[1] == d and shift_period.get(key[2]) == p:
                        terms.append(v)
            if terms:
                model.addCons(quicksum(terms) <= mx, name=f"periodrun_{n}_{p}_{i}")

# Incompatibilities
for (na, nb, sh) in inc_hard_shift:
    for d in DAYS:
        if sh is None:
            terms = [v for key, v in x.items() if key[0] in (na, nb) and key[1] == d]
            # same shift same day: for each shift, x[na,d,s,*] + x[nb,d,s,*] <= 1
            for s in set(key[2] for key in x.keys()):
                t = [v for key, v in x.items() if key[0] in (na, nb) and key[1] == d and key[2] == s]
                if t:
                    model.addCons(quicksum(t) <= 1, name=f"inc_{na}_{nb}_{d}_{s}")
        else:
            t = [v for key, v in x.items() if key[0] in (na, nb) and key[1] == d and key[2] == sh]
            if t:
                model.addCons(quicksum(t) <= 1, name=f"inc_{na}_{nb}_{d}_{sh}")

# Soft incompatibilities
for (na, nb, scope, sh, pen) in inc_soft:
    for d in DAYS:
        if scope == "same_day":
            # penalty if both work on same day
            t_a = [v for key, v in x.items() if key[0] == na and key[1] == d]
            t_b = [v for key, v in x.items() if key[0] == nb and key[1] == d]
            if t_a and t_b:
                y = model.addVar(name=f"incsoft_{na}_{nb}_{d}", vtype="B", lb=0, ub=1, obj=pen)
                model.addCons(quicksum(t_a) <= y, name=f"incsoft_a_{na}_{nb}_{d}")
                model.addCons(quicksum(t_b) <= y, name=f"incsoft_b_{na}_{nb}_{d}")
        elif scope == "same_shift" and sh:
            t = [v for key, v in x.items() if key[0] in (na, nb) and key[1] == d and key[2] == sh]
            if len(t) >= 2:
                y = model.addVar(name=f"incsoft_{na}_{nb}_{d}_{sh}", vtype="B", lb=0, ub=1, obj=pen)
                model.addCons(t[0] <= y, name=f"incsoft_a2_{na}_{nb}_{d}_{sh}")
                model.addCons(t[1] <= y, name=f"incsoft_b2_{na}_{nb}_{d}_{sh}")

# Charge coverage
for cr in charge:
    for d in DAYS:
        if cr["scope"] == "weekend" and not day_is_weekend[d]:
            continue
        # Early staffed indicator
        early_terms = [v for key, v in x.items() if key[1] == d and shift_period.get(key[2]) == cr["period"]]
        if not early_terms:
            continue
        # charge nurses in pool assigned to cr["skill"] in cr["period"] on d
        charge_terms = [v for key, v in x.items() if key[0] in cr["pool"] and key[1] == d and key[3] == cr["skill"] and shift_period.get(key[2]) == cr["period"]]
        if not charge_terms:
            # no one can satisfy; if hard, infeasible; else skip
            continue
        # short = max(0, cr["min"] - sum(charge_terms)) * [early staffed]
        # Simplify: penalty per missing, only when early is staffed
        # Use: sum(charge_terms) + missing >= cr["min"] when early staffed
        # Since early staffed is almost always true in feasible solutions, just enforce soft
        missing = model.addVar(name=f"charge_{cr['rule_id'] if 'rule_id' in cr else 'x'}_{d}", vtype="C", lb=0, ub=cr["min"], obj=0.0)
        model.addCons(quicksum(charge_terms) + missing >= cr["min"], name=f"chargecons_{d}")
        model.chgVarObj(missing, cr["penalty"])

# Fairness
for fr in fair:
    pool = fr["pool"]
    if fr["metric"] == "period_assignments":
        counts = {}
        for n in pool:
            terms = [v for key, v in x.items() if key[0] == n and key[3] == fr["skill"] and shift_period.get(key[2]) == fr["period"]]
            if fr["scope"] == "weekday":
                terms = [v for key, v in x.items() if key[0] == n and key[3] == fr["skill"] and shift_period.get(key[2]) == fr["period"] and not day_is_weekend[key[1]]]
            elif fr["scope"] == "weekend":
                terms = [v for key, v in x.items() if key[0] == n and key[3] == fr["skill"] and shift_period.get(key[2]) == fr["period"] and day_is_weekend[key[1]]]
            counts[n] = quicksum(terms) if terms else 0
    elif fr["metric"] == "counted_assignments":
        counts = {}
        for n in pool:
            c = contract_of(n)
            workdays = set(c["working_weekdays"].split(";"))
            terms = []
            for key, v in x.items():
                if key[0] == n:
                    if fr["scope"] == "weekend" and not day_is_weekend[key[1]]:
                        continue
                    terms.append(v)
            if (n,) and any((n, d) in a for d in DAYS):
                for d in DAYS:
                    if (n, d) in a and day_weekday[d] in workdays:
                        if fr["scope"] == "weekend" and not day_is_weekend[d]:
                            continue
                        terms.append(a[(n, d)])
            counts[n] = quicksum(terms) if terms else 0

    if not counts:
        continue
    # max-min imbalance
    maxv = model.addVar(name=f"fairmax_{fr['rule_id']}", vtype="C", lb=0, ub=31, obj=0.0)
    minv = model.addVar(name=f"fairmin_{fr['rule_id']}", vtype="C", lb=0, ub=31, obj=0.0)
    for n in pool:
        if n in counts:
            model.addCons(counts[n] <= maxv, name=f"fairmax_{fr['rule_id']}_{n}")
            model.addCons(counts[n] >= minv, name=f"fairmin_{fr['rule_id']}_{n}")
    imb = model.addVar(name=f"fairimb_{fr['rule_id']}", vtype="C", lb=0, ub=31, obj=0.0)
    model.addCons(maxv - minv - fr["allowed"] <= imb, name=f"fairimb_{fr['rule_id']}")
    model.chgVarObj(imb, fr["penalty"])

# Non-standard shift penalty
for key, v in x.items():
    n, d, s, k = key
    if (n, k, s) in elig and elig[(n, k, s)] == 0:
        model.chgVarObj(v, W["standard_shift"])

# Objective: set minimize (already default), vars have obj set
model.setMinimize()

model.optimize()

status = model.getStatus()
print(f"Solver status: {status}")
objval = model.getObjVal() if model.getNSols() > 0 else None
print(f"Objective: {objval}")
print(f"Time: {model.getSolTime(model.getBestSol()) if model.getNSols() > 0 else 0}")

# Extract solution
rows = []
sol = model.getBestSol() if model.getNSols() > 0 else None
if sol:
    for key, v in x.items():
        val = model.getVal(v)
        if val > 0.5:
            n, d, s, k = key
            rows.append((n, d, s, k))
    for key, v in a.items():
        val = model.getVal(v)
        if val > 0.5:
            n, d = key
            rows.append((n, d, "A", ""))

# Sort rows
rows.sort(key=lambda r: (r[0], day_idx[r[1]]))

with open(OUT, "w", newline="") as f:
    w = csv.writer(f)
    w.writerow(["nurse_id", "day", "shift_id", "skill_id"])
    for r in rows:
        w.writerow(r)

print(f"Wrote {len(rows)} rows to {OUT}")

# Validation
print("\n--- Validation ---")
# Check one state per day
from collections import defaultdict
state_count = defaultdict(int)
for n, d, s, k in rows:
    state_count[(n, d)] += 1
viol = {k: v for k, v in state_count.items() if v > 1}
print(f"One-state violations: {len(viol)}")

# Check coverage
cov_actual = defaultdict(int)
for n, d, s, k in rows:
    if s.startswith("Shift"):
        p = shift_period[s]
        cov_actual[(d, p, k)] += 1
cov_short = 0
for (d, p, k), (mn, opt, mx) in cov.items():
    actual = cov_actual.get((d, p, k), 0)
    if actual < mn:
        cov_short += mn - actual
print(f"Coverage min shortfalls: {cov_short}")

# Check contract bounds
for n in NURSES:
    c = contract_of(n)
    workdays = set(c["working_weekdays"].split(";"))
    cnt = 0
    wmin = 0
    for d in DAYS:
        has_shift = any(r[0] == n and r[1] == d and r[2].startswith("Shift") for r in rows)
        has_A = any(r[0] == n and r[1] == d and r[2] == "A" for r in rows)
        if has_shift:
            cnt += 1
            for r in rows:
                if r[0] == n and r[1] == d and r[2].startswith("Shift"):
                    wmin += shift_dur[r[2]]
        elif has_A and day_weekday[d] in workdays:
            cnt += 1
            wmin += int(c["average_work_minutes"])
    if cnt < int(c["min_assignments"]) or cnt > int(c["max_assignments"]):
        print(f"  {n}: assignments {cnt} outside [{c['min_assignments']}, {c['max_assignments']}]")
    if wmin < int(c["min_work_minutes"]) or wmin > int(c["max_work_minutes"]):
        print(f"  {n}: work minutes {wmin} outside [{c['min_work_minutes']}, {c['max_work_minutes']}]")

print("Validation complete.")
